<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import type {DetalleReporteCajaChica,FiltrosReporteCajaChica,FondoReporteCajaChica,RendicionReporteCajaChica,ResultadoReporteCajaChica} from '../interfaces/reporte-caja-chica.interface'
import {descargarReporteCajaChica,generarReporteCajaChica,listarFondosReporteCajaChica,listarRendicionesReporteCajaChica} from '../services/reporte-caja-chica'
const now=new Date(),months=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Setiembre','Octubre','Noviembre','Diciembre'],funds=ref<FondoReporteCajaChica[]>([]),returns=ref<RendicionReporteCajaChica[]>([]),result=ref<ResultadoReporteCajaChica>({}),generated=ref(false),loading=ref(false),downloading=ref(''),error=ref('')
const filters=reactive<FiltrosReporteCajaChica>({anio:now.getFullYear(),mes:now.getMonth()+1,tipo_fondo_caja_chica_id:0,rendicion_caja_chica_id:0,tipo_reporte:'RENDICION_CAJA_CHICA'}),rows=computed<DetalleReporteCajaChica[]>(()=>result.value.detalle??[]),money=(v:unknown)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v)||0),msg=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
const totals=computed(()=>({subtotal:result.value.totales?.subtotal??rows.value.reduce((s,x)=>s+(Number(x.subtotal)||0),0),impuesto:result.value.totales?.impuesto??rows.value.reduce((s,x)=>s+(Number(x.impuesto)||0),0),otros:result.value.totales?.otros??rows.value.reduce((s,x)=>s+(Number(x.otros)||0),0),total:result.value.totales?.total_general??result.value.totales?.total??rows.value.reduce((s,x)=>s+(Number(x.total)||0),0)}))
async function loadFunds(){try{funds.value=await listarFondosReporteCajaChica()}catch(e){error.value=msg(e)}}
async function loadReturns(){returns.value=[];filters.rendicion_caja_chica_id=0;generated.value=false;if(!filters.tipo_fondo_caja_chica_id)return;try{returns.value=await listarRendicionesReporteCajaChica(filters.tipo_fondo_caja_chica_id)}catch(e){error.value=msg(e)}}
function valid(){if(!filters.anio||!filters.mes)return'Seleccione año y mes.';if(!filters.tipo_fondo_caja_chica_id)return'Seleccione el fondo.';if(!filters.rendicion_caja_chica_id)return'Seleccione la rendición.';return''}
async function preview(){const issue=valid();if(issue)return error.value=issue;loading.value=true;error.value='';try{result.value=await generarReporteCajaChica(filters);generated.value=true}catch(e){error.value=msg(e)}finally{loading.value=false}}
async function download(format:'pdf'|'excel'){const issue=valid();if(issue)return error.value=issue;downloading.value=format;try{await descargarReporteCajaChica(format,filters)}catch(e){error.value=msg(e)}finally{downloading.value=''}}
onMounted(loadFunds)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Reporte de caja chica</nav><header class="hero"><b>RP</b><div><small>MIA · FINANZAS · CAJA CHICA</small><h1>Reporte de caja chica</h1><p>Consulta y exportación de rendiciones, documentos y gastos por rubro.</p></div></header><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Año<input v-model.number="filters.anio" type="number" min="2000" max="2100"></label><label>Mes<select v-model.number="filters.mes"><option v-for="(x,i) in months" :key="x" :value="i+1">{{x}}</option></select></label><label>Fondo<select v-model.number="filters.tipo_fondo_caja_chica_id" @change="loadReturns"><option :value="0">Seleccione</option><option v-for="x in funds" :key="x.id" :value="x.id">{{x.codigo}} · {{x.detalle}}</option></select></label><label>Rendición<select v-model.number="filters.rendicion_caja_chica_id" :disabled="!filters.tipo_fondo_caja_chica_id"><option :value="0">Seleccione</option><option v-for="x in returns" :key="x.id" :value="x.id">{{x.numero_rendicion}} · {{x.fecha}} · S/ {{money(x.total_general)}}</option></select></label><label>Tipo de reporte<select v-model="filters.tipo_reporte"><option value="RENDICION_CAJA_CHICA">Rendición de caja chica</option><option value="DETALLE_RENDICION">Detalle de rendición</option><option value="FONDO_RUBROS">Gasto por rubros</option><option value="LISTADO_ANUAL_FONDO">Gastos por comprobantes</option></select></label><div class="buttons"><button @click="preview">{{loading?'Generando…':'Generar'}}</button><button class="pdf" @click="download('pdf')">{{downloading==='pdf'?'Descargando…':'PDF'}}</button><button class="excel" @click="download('excel')">{{downloading==='excel'?'Descargando…':'Excel'}}</button></div></section><section v-if="generated" class="summary"><b>Rendición: {{result.cabecera?.numero_rendicion??'—'}}</b><span>Fecha: {{result.cabecera?.fecha??'—'}}</span></section><section class="card"><div v-if="loading||!generated||!rows.length" class="empty">{{loading?'Procesando…':!generated?'Seleccione los filtros y genere el reporte.':'No se encontraron documentos.'}}</div><div v-else class="scroll"><table><thead><tr><th>#</th><th>Documento</th><th>Fecha</th><th>Serie</th><th>Número</th><th>Proveedor / trabajador</th><th>RUC / DNI</th><th>Rubro</th><th>Cuenta</th><th>Valor</th><th>Impuesto</th><th>Otros</th><th>Total</th></tr></thead><tbody><tr v-for="x in rows" :key="x.item"><td>{{x.item}}</td><td>{{x.tipo_documento}}</td><td>{{x.fecha_documento}}</td><td>{{x.serie}}</td><td>{{x.numero}}</td><td>{{x.nombre_persona}}</td><td>{{x.codigo_persona}}</td><td>{{x.rubro}}</td><td>{{x.cuenta_contable}}</td><td class="num">{{money(x.subtotal)}}</td><td class="num">{{money(x.impuesto)}}</td><td class="num">{{money(x.otros)}}</td><td class="num">{{money(x.total)}}</td></tr></tbody><tfoot><tr><th colspan="9">TOTALES</th><th>{{money(totals.subtotal)}}</th><th>{{money(totals.impuesto)}}</th><th>{{money(totals.otros)}}</th><th>{{money(totals.total)}}</th></tr></tfoot></table></div></section></div></template>
<style scoped>.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}.hero{display:flex;gap:14px;padding:20px;border-left:5px solid var(--a);background:#fff}.hero>b{padding:16px;border-radius:10px;color:#fff;background:var(--a)}.hero small{color:var(--a);font-size:.5rem}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;font-size:.65rem}.flash{padding:10px;color:#9b3d48;background:#fdebee}.filters{margin-top:12px;padding:14px;display:flex;align-items:end;gap:9px;flex-wrap:wrap;background:#fff}.filters label{min-width:130px;flex:1;display:grid;gap:5px;font-size:.5rem;font-weight:700}input,select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff}.buttons{display:flex;gap:6px}button{padding:9px 13px;border:0;border-radius:6px;color:#fff;background:var(--a)}.pdf{background:#b74b54}.excel{background:#27875f}.summary{display:flex;gap:20px;margin-top:12px;padding:12px;background:#eaf4f5}.card{margin-top:12px;background:#fff}.empty{padding:50px;text-align:center}.scroll{overflow:auto}table{width:100%;min-width:1200px;border-collapse:collapse;font-size:.48rem}th,td{padding:8px;border-bottom:1px solid #e3e9eb;text-align:left}thead th{color:#fff;background:#435d6c}tfoot th{background:#eaf1f2}.num{text-align:right}@media(max-width:650px){.filters{display:grid}.hero>b{display:none}}</style>